public class RevertAction : SyncAction {

	public static readonly string MENU_NAME = "Revert Data Types From";

	public RevertAction(DataTypeManagerPlugin plugin, ArchiveManager archiveManager,
			DataTypeManager dtm, DataTypeStoreNode archiveNode, SourceArchive sourceArchive,
			bool isEnabled) : base("Revert Data Type Changes", plugin, archiveManager, dtm, archiveNode,
			sourceArchive, isEnabled)
    {
		setPopupMenuData(new MenuData(new string[] { MENU_NAME, sourceArchive.getName() }));
		setHelpLocation(new HelpLocation(plugin.getName(), getHelpTopic()));

	}

	/* @Override */
	protected int getMenuOrder() {
		return 3;
	}

	/* @Override */
	protected string getHelpTopic() {
		return "Revert_Data_Types";
	}

	/* @Override */
	protected bool isAppropriateForAction(DataTypeSyncInfo info) {

		switch (info.getSyncState()) {
			case COMMIT:
			case CONFLICT:
				return true;
			default:
				return false;
		}
	}

	/* @Override */
	protected bool isPreselectedForAction(DataTypeSyncInfo info) {
		return false;
	}

	/* @Override */
	protected string getOperationName() {
		return "Revert";
	}

	/* @Override */
	protected void applyOperation(DataTypeSyncInfo info) {
		info.revert();
